<?php require_once 'includes/db.php';require_once 'includes/auth.php';require_login();$uid=$_SESSION['user_id'];
$total=$conn->query("SELECT COALESCE(SUM(amount),0) n FROM donations WHERE user_id=$uid")->fetch_assoc()['n'];$count=$conn->query("SELECT COUNT(*) n FROM donations WHERE user_id=$uid")->fetch_assoc()['n'];$items=$conn->query("SELECT * FROM item_donations WHERE user_id=$uid ORDER BY id DESC");$recent=$conn->query("SELECT d.*,c.title FROM donations d LEFT JOIN campaigns c ON c.id=d.campaign_id WHERE d.user_id=$uid ORDER BY d.id DESC LIMIT 5");
$page_title='Dashboard';include 'includes/header.php';?><div class="top-actions"><div><h2>Welcome, <?=e($_SESSION['name'])?></h2><p class="small">Your donation activity</p></div><a class="btn" href="donate.php">Make Donation</a></div><div class="grid"><div class="card"><h3>Your Overall Donations</h3><div class="stat">₹<?=number_format($total,2)?></div></div><div class="card"><h3>Donation Count</h3><div class="stat"><?=$count?></div></div><div class="card"><h3>Items Donated</h3><div class="stat"><?=$items->num_rows?></div></div></div><h3>Recent Donations</h3><div class="table-wrap"><table class="table"><tr><th>Date</th><th>Campaign</th><th>Amount</th><th>Payment</th></tr><?php while($d=$recent->fetch_assoc()):?><tr><td><?=e($d['created_at'])?></td><td><?=e($d['title']??'General Donation')?></td><td>₹<?=number_format($d['amount'],2)?></td><td><?=e($d['payment_method'])?></td></tr><?php endwhile;?></table></div><h3>Donate Items Here</h3><div class="card"><form method="post" action="donate_item.php"><div class="form-group"><label>Item Name</label><input name="item_name" required></div><div class="form-group"><label>Quantity</label><input type="number" min="1" name="quantity" value="1" required></div><div class="form-group"><label>Notes</label><textarea name="notes"></textarea></div><button class="btn" type="submit">Donate Item</button></form></div><?php include 'includes/footer.php';?>
